accepted.test:
def test_html_hexadecimal_default_is_enabled():
    assert slugify('&#x17D;') == 'z'
    assert slugify('&#x17D;', allow_unicode=True) == 'ž'

def test_add_uppercase_char_unpacks_each_item():
    char_list = [('A', 'b')]
    assert add_uppercase_char(char_list) == [('A', 'b')]

def test_add_uppercase_char_inserts_missing_uppercase_pair():
    class GuardedList(list):
        def insert(self, index, value):
            if len(self) > 4:
                raise AssertionError('runaway insertion')
            list.insert(self, index, value)

    char_list = GuardedList([('a', 'b')])
    assert add_uppercase_char(char_list) == [('A', 'B'), ('a', 'b')]

def test_add_uppercase_char_insert_called_with_index_and_value():
    calls = []

    class RecordingList(list):
        def insert(self, *args):
            calls.append(args)

    add_uppercase_char(RecordingList([('ä', 'ae')]))
    assert len(calls) == 1
    assert len(calls[0]) == 2
    assert calls[0] == (0, ('Ä', 'Ae'))

def test_add_uppercase_char_insert_receives_the_uppercase_pair():
    calls = []

    class RecordingList(list):
        def insert(self, *args):
            calls.append(args)

    add_uppercase_char(RecordingList([('ä', 'ae')]))
    assert calls == [(0, ('Ä', 'Ae'))]

def test_add_uppercase_char_insert_index_is_an_integer():
    calls = []

    class RecordingList(list):
        def insert(self, *args):
            calls.append(args)

    add_uppercase_char(RecordingList([('ä', 'ae')]))
    assert len(calls) == 1
    assert calls[0][0] is not None
    assert calls[0] == (0, ('Ä', 'Ae'))

def test_add_uppercase_char_insert_value_is_not_none():
    calls = []

    class RecordingList(list):
        def insert(self, *args):
            calls.append(args)

    add_uppercase_char(RecordingList([('ä', 'ae')]))
    assert len(calls) == 1
    assert calls[0][-1] == ('Ä', 'Ae')

